const seen = new Set();
const cleaned = [];
for (const item of items) {
  const row = item.json;
  const email = String(row.email || '').trim().toLowerCase();
  if (!email || seen.has(email)) continue;
  seen.add(email);
  cleaned.push({
    json: {
      name: String(row.name || '').trim(),
      email,
      company: String(row.company || '').trim()
    }
  });
}
return cleaned;
